    @classmethod
    def normalize(cls, val: str) -> str:
        # Cap the length to 255 to prevent indexes from being too long
        return unidecode(val).translate(_NORMALIZE_PUNCTUATION_TABLE).lower().strip()[:255]

    def update(self, **kwargs):
